def calculate_probability(type1_expired: int = 5, type2_expired: int = 3) -> float:
    """Calculates the probability that a chosen beer case is of Type I given that 2 out of 10 randomly selected cans are expired.

    Args:
        type1_expired: Number of expired cans in a Type I case. Defaults to 5.
        type2_expired: Number of expired cans in a Type II case. Defaults to 3.

    Returns:
        The probability that the chosen case is of Type I, rounded to two decimal places.
    """
    type1_cases = 2 * type2_cases  # Twice the number of Type II cases are Type I cases

    # Calculate probabilities for both types given 2 expired cans out of 10
    prob_type1_given_2_expired = (
        (type1_cases * (calculate_combinations(type1_expired, 2) * calculate_combinations(19, 8)))
        / (
            (type1_cases * calculate_combinations(24, 10)) + (type2_cases * calculate_combinations(24, 10))
        )
    )

    prob_type2_given_2_expired = (
        (type2_cases * (calculate_combinations(type2_expired, 2) * calculate_combinations(21, 8)))
        / (
            (type1_cases * calculate_combinations(24, 10)) + (type2_cases * calculate_combinations(24, 10))
        )
    )

    # Apply Bayes' Theorem to find the probability of Type I given 2 expired cans
    prob_type1 = (
        prob_type1_given_2_expired * (type1_cases / (type1_cases + type2_cases)))
    return round(prob_type1, 2)


def calculate_combinations(n: int, k: int) -> int:
    """Calculates the number of combinations for n items taken k at a time."""
    if k < 0 or k > n:
        raise ValueError("k must be between 0 and n")
    return factorial(n) // (factorial(k) * factorial(n - k))


def factorial(n: int) -> int:
    """Calculates the factorial of a non-negative integer."""
    if n == 0:
        return 1
    return n * factorial(n - 1)

