        type2_expired (int): Number of expired cans in a Type II case (default: 3).

    Returns:
        float: The probability of the chosen case being Type I, rounded to two decimal places.
    """
    type1_cases = 2 * type2_cases  # Twice the number of Type II cases are Type I
    total_cases = type1_cases + type2_cases

    # Calculate probabilities for each case type
    prob_type1_given_2_expired = (
        (type1_cases * calculate_probability_of_2_expired_in_type1()) / total_cases
    )
    prob_type2_given_2_expired = (
        (type2_cases * calculate_probability_of_2_expired_in_type2()) / total_cases
    )

    # Apply Bayes' Theorem to find the probability of Type I given 2 expired cans
    return round((prob_type1_given_2_expired) / (prob_type1_given_2_expired + prob_type2_given_2_expired), 2)


def calculate_probability_of_2_expired_in_type1():
    """Calculates the probability of finding 2 expired cans in a Type I case."""
    return (
        calculate_combinations(24, 2) * calculate_combinations(5, 2) / calculate_combinations(24, 2)
    )


def calculate_probability_of_2_expired_in_type2():
    """Calculates the probability of finding 2 expired cans in a Type II case."""
    return (
        calculate_combinations(24, 2) * calculate_combinations(3, 2) / calculate_combinations(24, 2)
    )


def calculate_combinations(n, k):
    """Calculates the number of combinations for n items taken k at a time."""
    return factorial(n) // (factorial(k) * factorial(n - k))


def factorial(n):
    """Calculates the factorial of a non-negative integer."""
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

