from typing import Optional


def calculate_probability(type1_expired: Optional[int] = 5, type2_expired: Optional[int] = 3) -> float:
    """Calculates the probability that a chosen beer case is of Type I given that 2 out of 10 randomly selected cans are expired.

    Args:
        type1_expired: The number of expired cans in a Type I case (default: 5).
        type2_expired: The number of expired cans in a Type II case (default: 3).

    Returns:
        The probability that the chosen case is of Type I, rounded to two decimal places.
    """

    type1_cases = 2 * type2_cases  # Number of Type I cases is twice the number of Type II cases

    # Calculate probabilities for both types given 2 expired cans
    prob_type1_given_2_expired = _calculate_conditional_probability(
        type1_expired, type2_expired, type1_cases, 2  
    )

    prob_type2_given_2_expired = _calculate_conditional_probability(
        type2_expired, type1_expired, type2_cases, 2  
    )

    # Apply Bayes' Theorem to find the probability of Type I given 2 expired cans
    return round((prob_type1_given_2_expired * (type1_cases / (type1_cases + type2_cases))) , 2)


def _calculate_conditional_probability(
    case_expired: int, other_case_expired: int, case_count: int, expired_cans: int
) -> float:
    """Calculates the probability of a specific case type given a certain number of expired cans."""

    total_cases = case_count + (case_count / 2)  # Total cases is sum of both types
    total_expired = case_expired * case_count + other_case_expired * (case_count / 2)  # Total expired cans

    return _calculate_probability(
        total_cases, total_expired, case_count, expired_cans
    )


def _calculate_probability(
    total_cases: int, total_expired: int, case_count: int, expired_cans: int
) -> float:
    """Calculates the probability of a specific number of expired cans given total cases and expired cans."""

    # Calculate combinations for choosing expired and non-expired cans
    combinations_expired = _calculate_combinations(total_expired, expired_cans)
    combinations_non_expired = _calculate_combinations(total_cases - total_expired, 10 - expired_cans)

    # Calculate the probability of the given number of expired cans
    return combinations_expired / (combinations_expired + combinations_non_expired)


def _calculate_combinations(n: int, k: int) -> int:
    """Calculates the number of combinations for choosing k items from a set of n."""

    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return _calculate_combinations(n - 1, k - 1) + _calculate_combinations(n - 1, k)

