def solve_tsp(distances: list[list[int]]) -> int:
    """Solves the Traveling Salesperson Problem using brute force.

    Args:
        distances: A 2D list representing the distance matrix between cities.
                   distances[i][j] is the cost of traveling from city i to city j.

    Returns:
        The minimum total travel cost.
    """

    num_cities = len(distances)
    min_cost = float('inf')

    def calculate_total_cost(route: list[int]) -> int:
        total_cost = 0
        for i in range(num_cities - 1):
            total_cost += distances[route[i]][route[i + 1]]
        total_cost += distances[route[-1]][route[0]]  # Return to starting city
        return total_cost

    def generate_permutations(start: int) -> list[list[int]]:
        if start == num_cities:
            return [list(range(num_cities))]
        permutations = []
        for i in range(1, num_cities):
            if i != start:
                for permutation in generate_permutations(start + 1):
                    permutation.insert(0, i)
                    permutations.append(permutation)
        return permutations

    for permutation in generate_permutations(0):
        cost = calculate_total_cost(permutation)
        min_cost = min(min_cost, cost)

    return min_cost

