from itertools import combinations

def solve_octagon_prob(assignments: list[int]) -> int:
    """Calculates the probability that a randomly chosen triangle from an octagon with assigned numbers is a right triangle with vertices forming an arithmetic progression.

    Args:
        assignments: A list of eight natural numbers assigned to the vertices of the octagon.

    Returns:
        The sum of the numerator and denominator of the probability in simplest form as an integer.
    """
    n = len(assignments)
    count_right_arithmetic = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a, b, c = assignments[i], assignments[j], assignments[k]
                if is_right_triangle(a, b, c) and is_arithmetic_progression(a, b, c):
                    count_right_arithmetic += 1

    return count_right_arithmetic * 3 + n * (n - 1) * (n - 2) // 6


def is_right_triangle(a: int, b: int, c: int) -> bool:
    """Checks if a triangle with sides a, b, and c is a right triangle."""
    return a**2 + b**2 == c**2 or a**2 + c**2 == b**2 or b**2 + c**2 == a**2


def is_arithmetic_progression(a: int, b: int, c: int) -> bool:
    """Checks if three numbers form an arithmetic progression."""
    return (b - a) == (c - b)

