    """
    Calculates the probability that a randomly chosen triangle from an octagon with assigned numbers forms a right triangle and its sides are in arithmetic progression.

    Args:
        numbers: A list of eight natural numbers representing the vertices of the octagon.

    Returns:
        The sum of the numerator and denominator of the probability in simplest form (m + n).
    """

    n = len(numbers)
    count = 0  # Count of valid triangles

    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a, b, c = numbers[i], numbers[j], numbers[k]
                if is_right_triangle(a, b, c) and is_arithmetic_progression(a, b, c):
                    count += 1

    probability = count / (n * (n - 1) * (n - 2) // 6)  # Total number of possible triangles
    m, n = probability.numerator, probability.denominator
    return m + n


