        for j in range(working_hours // type_i_hours + 1):
            if i * type_i_raw <= raw_materials and j * type_i_hours <= working_hours:
                k = (raw_materials - i * type_i_raw) // type_ii_raw
                l = (working_hours - j * type_i_hours) // type_ii_hours
                if k * type_ii_raw <= raw_materials and l * type_ii_hours <= working_hours:
                    profit = i * type_i_profit + j * type_ii_profit
                    if profit > (m * type_i_profit + n * type_ii_profit):
                        m = i
                        n = j
    return m + 2 * n   
