def solve_min_products(fixed_cost: int, variable_cost: int, selling_price: int) -> int:
    """
    Calculates the minimum number of products that must be produced and sold for a business to start making a profit.

    Args:
        fixed_cost (int): The fixed monthly cost in VND.
        variable_cost (int): The variable cost per product in VND.
        selling_price (int): The selling price per product in VND.

    Returns:
        int: The minimum number of products to be sold for a profit.
    """

    def calculate_tax(x: int) -> int:
      if x < 100:
        return 0.1 * (x * selling_price)
      elif 100 <= x < 300:
        return 0.08 * (x * selling_price)
      else:
        return 0.05 * (x * selling_price)

    x = 1
    while True:
      revenue = x * selling_price
      cost = fixed_cost + x * variable_cost
      profit = revenue - cost - calculate_tax(x)
      if profit > 0:
        return x
      x += 1

