from typing import Tuple


def calculate_win_probability(p: float) -> float:
    """Calculates the probability of An winning a table tennis match.

    Args:
        p: The probability of An winning each individual set.

    Returns:
        The probability of An winning the match, rounded to two decimal places.
    """

    def calculate_sets_win(n_sets: int) -> float:
        """Calculates the probability of An winning n sets."""
        if n_sets == 3:
            return 1.0  # An wins if they win 3 sets
        elif n_sets < 3:
            return (p ** n_sets) * ((1 - p) ** (3 - n_sets)) * calculate_sets_win(n_sets + 1)

    return round(calculate_sets_win(0), 2)


# Test cases
assert calculate_win_probability(0.4) == 0.32
assert calculate_win_probability(0.5) == 0.5

