from typing import Union, Callable

def calculate_win_probability(p: float) -> float:
    """Calculates the probability of An winning a best-of-five table tennis match given the probability of winning each individual set.

    Args:
        p: The probability of An winning each individual set.

    Returns:
        The probability of An winning the match, rounded to two decimal places.
    """

    def calculate_sets_won(num_sets: int) -> float:
      """Calculates the probability of An winning a specific number of sets."""
      if num_sets == 3:  
        return 1.0
      elif num_sets == 0:
        return 0.0
      else:
        return sum([calculate_sets_won(i) * (p**i) * ((1-p)**(num_sets - i)) for i in range(num_sets + 1)])

    # Calculate the probability of An winning 3 sets out of a best-of-five
    win_probability = calculate_sets_won(3)

    return round(win_probability, 2)

