from typing import Callable

def calculate_win_probability(p: float) -> float:
    """Calculates the probability of An winning a best-of-five table tennis match given the probability of winning each individual set.

    Args:
        p: The probability of An winning each individual set.

    Returns:
        The probability of An winning the overall match, rounded to two decimal places.
    """

    def calculate_sets_won(sets_won: int) -> float:
      """Calculates the probability of An winning exactly 'sets_won' sets."""
      if sets_won == 3:
        return 1  # An wins if they have 3 sets
      elif sets_won < 3:
        return (p ** sets_won) * ((1 - p) ** (3 - sets_won)) * calculate_combinations(3, sets_won)

    def calculate_combinations(n: int, k: int) -> float:
      """Calculates the number of combinations for choosing 'k' items from a set of 'n'."""
      return factorial(n) // (factorial(k) * factorial(n - k))

    def factorial(n: int) -> int:
      """Calculates the factorial of a non-negative integer."""
      if n == 0:
        return 1
      else:
        return n * factorial(n - 1)

    # Calculate probabilities for An winning 3, 2, 1 set scenarios
    probability_3_sets = calculate_sets_won(3)
    probability_2_sets = calculate_sets_won(2)
    probability_1_set = calculate_sets_won(1)

    # Sum the probabilities of winning scenarios
    total_win_probability = probability_3_sets + probability_2_sets + probability_1_set

    return round(total_win_probability, 2)

