from typing import Tuple

def calculate_win_probability(p: float) -> float:
    """Calculates the probability of An winning a table tennis match given the probability of winning each set.

    Args:
        p: The probability of An winning an individual set.

    Returns:
        The probability of An winning the overall match, rounded to two decimal places.
    """

    def calculate_sets_won(num_sets: int) -> Tuple[float, float]:
      """Calculates the probabilities of An and Binh winning a specific number of sets."""
      if num_sets == 3:
        return (1, 0)  # An wins if they have 3 sets
      elif num_sets == 2:
        return (p**2 * (1 - p), (1 - p)**2 * p) # Probability of An winning 2 sets and Binh winning 1
      else:
        raise ValueError("Invalid number of sets")

    # Calculate probabilities for all possible scenarios where An wins
    win_probabilities = [calculate_sets_won(i)[0] for i in range(3, 7)] 

    return round(sum(win_probabilities), 2)

