import numpy as np
from scipy.optimize import minimize

def f(x):
  """Cubic function defining the garden's boundary."""
  return x**3 - 2*x**2 + x  # Replace with the actual cubic function

def g(x):
  """Linear function defining the road."""
  return (x + 1) / (x - 2)

def distance_point_to_curve(mx: float, my: float) -> float:
  """Calculates the distance between a point (mx, my) and the curve g(x)."""
  def dist_func(x):
    return np.sqrt((x - mx)**2 + (g(x) - my)**2)

  # Find the x-coordinate on the road closest to the point
  result = minimize(dist_func, 3)  # Start with an initial guess of x=3
  closest_x = result.x

  return np.sqrt((closest_x - mx)**2 + (g(closest_x) - my)**2) * 10

def solve_min_distance(mx: float, my: float) -> float:
  """Calculates the shortest distance from a point in the garden to the road."""
  return distance_point_to_curve(mx, my)


# Test cases
assert solve_min_distance(3, 2) == 10.35
assert solve_min_distance(0, 0) == 46.06

print("All test cases passed!")

