```python
import random

def calculate_3430p(n: int) -> float:
    """Calculates the value of 3430 * p, where p is the probability that the sum of numbers in each column of a 3x3 grid is 0 given that the sum of numbers in each row is 0.

    Args:
        n: An integer representing the number of times to simulate the grid filling process.

    Returns:
        The calculated value of 3430 * p as a float, rounded to two decimal places.
    """
    success_count = 0
    for _ in range(n):
        grid = [[random.choice([-1, 0, 1]) for _ in range(3)] for _ in range(3)]

        # Check if the sum of each row is 0
        for row in grid:
            if sum(row) != 0:
                break
        else:
            # If all rows have sum 0, check if columns also have sum 0
            for col in range(3):
                if sum([grid[i][col] for i in range(3)]) != 0:
                    break
            else:
                success_count += 1

    p = success_count / n
    return round(3430 * p, 2)



```

