from typing import Tuple


def count_triangles_same_color(n: int) -> int:
    """Counts the number of triangles in a polygon with n vertices where all sides are the same color."""
    count = 0
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                # Check if all sides are blue (edges)
                if (i + 1) % 2 == 0 and (j + 1) % 2 == 0 and (k + 1) % 2 == 0:
                    count += 1
    return count


def solve_polygon_triangle_color(n: int) -> int:
    """Calculates the probability of a randomly chosen triangle having all sides of the same color."""
    total_triangles = (n * (n - 1) * (n - 2)) // 6  # Formula for calculating the number of triangles in a polygon
    same_color_triangles = count_triangles_same_color(n)
    probability = same_color_triangles / total_triangles
    return int(probability * 100) + 100


# Test cases
assert solve_polygon_triangle_color(20) == 97
assert solve_polygon_triangle_color(6) == 11

