def solve_polygon_triangle_color(n: int) -> int:
    """
    A regular polygon has n vertices. All edges of the polygon are painted blue and all diagonals are painted red. Let X be the set of all triangles whose vertices are vertices of the polygon. A triangle is chosen at random from X. Find the probability that the chosen triangle has all three sides of the same color. The result should be expressed as a simplified fraction a/b.

    Args:
        n: The number of vertices of the polygon.

    Returns:
        The sum of the numerator and denominator of the simplified fraction representing the probability.
    """
    total_triangles = calculate_total_triangles(n)
    same_color_triangles = calculate_same_color_triangles(n)
    probability = same_color_triangles / total_triangles
    return int(numerator(probability)) + int(denominator(probability))

def calculate_total_triangles(n: int) -> int:
    """Calculates the total number of triangles possible in a polygon with n vertices."""
    return n * (n - 1) * (n - 2) // 6

def calculate_same_color_triangles(n: int) -> int:
    """Calculates the number of triangles with all sides of the same color."""
    #  Triangles with all blue sides (edges)
    blue_triangles = n * (n - 1) // 2  
    return blue_triangles

def numerator(p: float) -> int:
    """Extracts the numerator of a fraction represented as a float."""
    return int(p * denominator(p))

def denominator(p: float) -> int:
    """Extracts the denominator of a fraction represented as a float."""
    return int(1 / (p - int(p)))

