```python
def calculate_probability_score(num_questions: int, points_per_correct: int, points_per_incorrect: int, target_score: int) -> float:
    """Calculates the probability of a student scoring a specific target score in a multiple-choice test.

    Args:
        num_questions: The number of questions in the test.
        points_per_correct: The number of points awarded for a correct answer.
        points_per_incorrect: The number of points deducted for an incorrect answer.
        target_score: The desired target score.

    Returns:
        The probability of scoring the target score, rounded to two decimal places.
    """
    if num_questions * points_per_correct < target_score or target_score < 0:
      return 0.0

    probability = 0
    for i in range(num_questions):
        # Calculate the number of correct answers needed for the target score
        correct_answers_needed = (target_score - i * points_per_incorrect) // points_per_correct
        # Calculate the probability of getting the required number of correct answers
        probability += calculate_combinations(num_questions, correct_answers_needed) * (
            (1 / 4) ** correct_answers_needed
        ) * ((3 / 4) ** (num_questions - correct_answers_needed))

    return round(probability, 2)


def calculate_combinations(n: int, k: int) -> int:
    """Calculates the number of combinations for a given n and k."""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return calculate_combinations(n - 1, k - 1) + calculate_combinations(n - 1, k)



