def is_valid_placement(triangles: List[Tuple[int, str]], face_index: int) -> bool:
    """Checks if placing a triangle on the given face is valid."""
    if face_index % 2 == 0:  # Even-indexed faces share an edge with odd-indexed ones
        neighbor_face = face_index + 1
    else:
        neighbor_face = face_index - 1

    current_color = triangles[face_index][1]
    neighbor_color = triangles[neighbor_face][1]
    if current_color == neighbor_color:
        return False  # Colors must differ on adjacent faces

    current_number = triangles[face_index][0]
    neighbor_number = triangles[neighbor_face][0]
    if current_number == neighbor_number:
        return False  # Numbers must differ on faces sharing a vertex

    return True


def calculate_final_value(num_ways: int) -> float:
