def calculate_p_scaled(num_slots: int, num_books: int, scale_factor: int) -> int:
    """Calculates the scaled probability of a specific book distribution on bookshelves.

    Args:
        num_slots (int): The number of bookshelf slots.
        num_books (int): The number of identical books to place.
        scale_factor (int): A factor to multiply the calculated probability by.

    Returns:
        int: The scaled probability as an integer.
    """

    if num_slots < num_books or num_books <= 0 or num_slots <= 0:
        return 0  

    def is_valid_distribution(arrangement: list[int]) -> bool:
        """Checks if a book arrangement satisfies the given conditions."""
        for i in range(num_slots):
            if arrangement[i] == 2:
                if i > 0 and arrangement[i - 1] > 0:
                    return False
                if i < num_slots - 1 and arrangement[i + 1] > 0:
                    return False

        num_one_books = sum(1 for book in arrangement if book == 1)
        return num_one_books in (4, 6)

    total_arrangements = 10 ** num_books  # All possible arrangements of books
    valid_arrangements = 0

    for i in range(total_arrangements):
        arrangement = [0] * num_slots
        for j in range(num_books):
            while True:
                slot = random.randint(0, num_slots - 1)
                if arrangement[slot] == 0:
                    arrangement[slot] += 1
                    break

        if is_valid_distribution(arrangement):
            valid_arrangements += 1

    probability = valid_arrangements / total_arrangements
    return int(probability * scale_factor)

