def calculate_p_scaled(num_slots: int, num_books: int, scaling_factor: int) -> int:
    """Calculates the scaled probability of a specific book distribution on bookshelves.

    Args:
        num_slots: The number of bookshelf slots.
        num_books: The number of identical books to place.
        scaling_factor: A factor to multiply the calculated probability by.

    Returns:
        The scaled probability as an integer.
    """

    def is_valid_distribution(distribution: list[int]) -> bool:
        """Checks if a book distribution satisfies the given criteria."""
        slots_with_one_book = sum(1 for slot in distribution if slot == 1)
        slots_with_two_books = sum(1 for slot in distribution if slot == 2)

        if slots_with_one_book != 4 and slots_with_one_book != 6:
            return False

        for i in range(num_slots):
