    for distribution in itertools.product([0, 1, 2], repeat=num_slots):
        if is_valid_distribution(distribution):
            valid_arrangements += 1

    probability = valid_arrangements / total_arrangements  # Calculate probability
    return int(scaling_factor * probability)



