def calculate_p_scaled(num_slots: int, num_books: int, scale_factor: int) -> int:
    """Calculates the scaled probability of a specific book distribution.

    Args:
        num_slots: The number of bookshelf slots.
        num_books: The number of books to be placed.
        scale_factor: A factor to multiply the calculated probability by.

    Returns:
        The scaled probability as an integer.
    """

    if num_books > num_slots:
        return 0  # Not possible to place more books than slots

    total_arrangements = num_slots ** num_books  # Calculate total possible arrangements

    favorable_arrangements = 0  # Initialize count of favorable arrangements

    def is_valid_arrangement(arrangement: list[int]) -> bool:
        """Checks if a given arrangement satisfies the conditions."""
        for i in range(num_slots):
            if arrangement[i] > 2:
                return False  # Slot contains more than 2 books

        one_book_count = sum(1 for count in arrangement if count == 1)
        if one_book_count != 4 and one_book_count != 6:
            return False  # Incorrect number of slots with 1 book

        for i in range(num_slots):
            if arrangement[i] == 2 and (i == 0 or i == num_slots - 1 or arrangement[i - 1] > 0 or arrangement[i + 1] > 0):
                return False  # Two-book slot not surrounded by empty slots

        return True  # Arrangement satisfies all conditions

    for i in range(total_arrangements):
        arrangement = [0] * num_slots  # Create an initial arrangement with empty slots
        for j in range(num_books):
            while True:
                slot = random.randint(0, num_slots - 1)
                if arrangement[slot] < 2:
                    arrangement[slot] += 1
                    break  # Place the book in a valid slot

        if is_valid_arrangement(arrangement):
            favorable_arrangements += 1

    probability = favorable_arrangements / total_arrangements
    return int(probability * scale_factor)

