from typing import Tuple

def calculate_p_scaled(num_slots: int, num_books: int, scaling_factor: int) -> int:
    """Calculates the scaled probability of a specific book distribution on bookshelves.

    Args:
        num_slots: The number of bookshelf slots.
        num_books: The number of identical books to place.
        scaling_factor: A factor to multiply the calculated probability by.

    Returns:
        The scaled probability as an integer.
    """

    total_arrangements = factorial(num_slots)  # Calculate total possible arrangements

    valid_arrangements = 0
    for arrangement in generate_arrangements(num_slots, num_books):
        if is_valid_arrangement(arrangement):
            valid_arrangements += 1

    probability = valid_arrangements / total_arrangements  # Calculate probability

    return int(probability * scaling_factor)  # Scale the probability


def factorial(n: int) -> int:
    """Calculates the factorial of a non-negative integer."""
    if n == 0:
        return 1
    else:
        return n * factorial(n - 1)

def generate_arrangements(num_slots: int, num_books: int) -> list[Tuple[int, ...]]:
    """Generates all possible arrangements of books in the slots."""
    if num_books == 0:
        return [tuple(0 * i for i in range(num_slots))]  # Empty arrangement

    arrangements = []
    for i in range(num_slots):
        for sub_arrangement in generate_arrangements(num_slots - 1, num_books - 1):
            new_arrangement = list(sub_arrangement)
            new_arrangement.insert(i, 1)  # Insert book at position i
            arrangements.append(tuple(new_arrangement))

    return arrangements

def is_valid_arrangement(arrangement: Tuple[int, ...]) -> bool:
    """Checks if a given arrangement of books satisfies the conditions."""
    slots_with_one_book = 0
    slots_with_two_books = 0

    for i in range(len(arrangement) - 1):
        if arrangement[i] == 2 and (arrangement[i - 1] != 0 or arrangement[i + 1] != 0):
            return False  # Two books not surrounded by empty slots

        if arrangement[i] == 1:
            slots_with_one_book += 1

    if slots_with_one_book != 4 and slots_with_one_book != 6:
        return False  # Incorrect number of slots with one book

    return True

