from typing import Tuple

def calculate_p_scaled(num_slots: int, num_books: int, scaling_factor: int) -> int:
    """Calculates the scaled probability of a specific book distribution on bookshelves.

    Args:
        num_slots: The number of bookshelf slots.
        num_books: The number of identical books.
        scaling_factor: A factor to multiply the calculated probability by.

    Returns:
        The scaled probability as an integer.
    """

    # Calculate the total number of ways to arrange the books
    total_arrangements = factorial(num_slots) // (factorial(num_slots - num_books) * factorial(num_books))

    # Calculate the number of valid arrangements satisfying the given conditions
    valid_arrangements = 0
    for arrangement in generate_arrangements(num_slots, num_books):
        if is_valid_arrangement(arrangement):
            valid_arrangements += 1

    probability = valid_arrangements / total_arrangements

    return int(probability * scaling_factor)


def factorial(n: int) -> int:
    """Calculates the factorial of a non-negative integer."""
    if n == 0:
        return 1
    return n * factorial(n - 1)


def generate_arrangements(num_slots: int, num_books: int) -> list[Tuple[int, ...]]:
    """Generates all possible arrangements of books in the slots."""
    if num_books == 0:
        return [tuple(range(num_slots))]

    arrangements = []
    for i in range(num_slots):
        for arrangement in generate_arrangements(num_slots - 1, num_books - 1):
            arrangements.append((i,) + arrangement)
    return arrangements


def is_valid_arrangement(arrangement: Tuple[int, ...]) -> bool:
    """Checks if a given book arrangement satisfies the specified conditions."""
    # Check condition 1: No slot contains more than 2 books
    for i in range(len(arrangement)):
        if arrangement.count(i) > 2:
            return False

    # Check condition 2: Exactly 4 or 6 slots contain exactly 1 book
    num_slots_with_one_book = sum(1 for count in [arrangement.count(i) for i in range(len(arrangement))] if count == 1)
    if num_slots_with_one_book != 4 and num_slots_with_one_book != 6:
        return False

    # Check condition 3: Any slot containing 2 books must be surrounded by empty slots
    for i in range(len(arrangement)):
        if arrangement.count(i) == 2:
            if i > 0 and arrangement[i - 1] != -1:  # Left neighbor is not empty
                return False
            if i < len(arrangement) - 1 and arrangement[i + 1] != -1:  # Right neighbor is not empty
                return False

    return True

