def calculate_probability(total_tickets: int, num_drawn: int) -> float:
    """Calculates the probability of drawing at least two prime numbers and an even sum from a set of tickets.

    Args:
        total_tickets: The total number of tickets in the box.
        num_drawn: The number of tickets drawn simultaneously.

    Returns:
        The probability as a percentage rounded to one decimal place.
    """
    prime_count = 0
    for i in range(2, total_tickets + 1):
        is_prime = True
        for j in range(2, int(i**0.5) + 1):
            if i % j == 0:
                is_prime = False
                break
        if is_prime:
            prime_count += 1

    # Calculate the probability of drawing at least two prime numbers and an even sum
    probability = 0
    for combinations in range(2, num_drawn + 1):  
        # Calculate combinations of drawing prime numbers
        num_combinations = calculate_combinations(prime_count, combinations)

        # Calculate combinations of drawing any numbers
        total_combinations = calculate_combinations(total_tickets, num_drawn)

        # Calculate probability for current combination of primes
        probability += (num_combinations / total_combinations) * calculate_even_sum_probability(combinations)

    return round(probability * 100, 1)


def calculate_combinations(n: int, k: int) -> int:
    """Calculates the number of combinations."""
    if k < 0 or k > n:
        return 0
    if k == 0 or k == n:
        return 1
    return (calculate_combinations(n - 1, k - 1) + calculate_combinations(n - 1, k))


def calculate_even_sum_probability(num_primes: int) -> float:
    """Calculates the probability of an even sum given the number of prime numbers."""
    if num_primes % 2 == 0:
        return 1.0  # Even number of primes guarantees an even sum
    else:
        return 0.5  # Odd number of primes has a 50/50 chance of an even sum



