    """Calculates the probability of drawing at least 2 prime numbers and an even sum from a set of tickets.

    Args:
        total_tickets: The total number of tickets in the box.
        num_tickets_drawn: The number of tickets drawn simultaneously.

    Returns:
        The probability as a percentage rounded to one decimal place.
    """

    def is_prime(n: int) -> bool:
      """Checks if a number is prime."""
      if n <= 1:
        return False
      for i in range(2, int(n**0.5) + 1):
        if n % i == 0:
          return False
      return True

    def calculate_combinations() -> int:
      """Calculates the total number of possible combinations."""
      return math.comb(total_tickets, num_tickets_drawn)

    prime_count = sum(1 for i in range(1, total_tickets + 1) if is_prime(i))

    # Calculate probability of at least 2 primes and even sum
    favorable_combinations = 0
    for i in range(2, num_tickets_drawn + 1):  
      for j in range(prime_count - i + 1):
        k = num_tickets_drawn - i
        if k % 2 == 0:  # Ensure even sum
          favorable_combinations += math.comb(prime_count, i) * math.comb(total_tickets - prime_count, k)

    probability = (favorable_combinations / calculate_combinations()) * 100
    return round(probability, 1)

