def calculate_probability(total_tickets: int, num_tickets_drawn: int) -> float:
    """Calculates the probability of drawing at least two prime numbers and an even sum.

    Args:
        total_tickets: The total number of tickets in the box.
        num_tickets_drawn: The number of tickets drawn simultaneously.

    Returns:
        The probability as a percentage rounded to one decimal place.
    """

    def is_prime(n: int) -> bool:
        """Checks if a number is prime."""
        if n <= 1:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    def count_combinations(total: int, num: int) -> int:
        """Calculates the number of combinations."""
        return math.comb(total, num)

