        prime_combinations = count_combinations(prime_count, i)
        non_prime_combinations = count_combinations(total_tickets - prime_count, num_tickets_drawn - i)

        probability += (prime_combinations * non_prime_combinations * even_sum_combinations) / count_combinations(total_tickets, num_tickets_drawn)

    return round(probability * 100, 1)



