def calculate_probability(total_tickets: int, chosen_tickets: int) -> float:
    """Calculates the probability of having at least 2 prime numbers and an even sum."""
    prime_count = sum(1 for i in range(1, total_tickets + 1) if is_prime(i))

    total_combinations =  math.comb(total_tickets, chosen_tickets)

    favorable_combinations = 0
    for i in range(prime_count):
