```python
from typing import List, Tuple

def is_prime(num: int) -> bool:
    """Checks if a number is prime."""
    if num <= 1:
        return False
    for i in range(2, int(num**0.5) + 1):
        if num % i == 0:
            return False
    return True

def calculate_probability(total_tickets: int, chosen_tickets: int) -> float:
    """Calculates the probability of having at least 2 prime numbers and an even sum."""
    prime_count = 0
    for i in range(1, total_tickets + 1):
        if is_prime(i):
            prime_count += 1

    # Calculate the number of ways to choose 4 tickets with at least 2 primes
    ways_with_atleast_two_primes = 0
    for i in range(2, min(chosen_tickets, prime_count) + 1):
        for j in range(i, chosen_tickets):
            # Calculate combinations for the remaining tickets (non-prime)
            combinations = calculate_combinations(total_tickets - prime_count, chosen_tickets - i - j)
            ways_with_atleast_two_primes += combinations

    # Calculate the total number of ways to choose 4 tickets
    total_combinations = calculate_combinations(total_tickets, chosen_tickets)

    # Calculate the probability
    probability = (ways_with_atleast_two_primes / total_combinations) * 100

    return round(probability, 1)

def calculate_combinations(n: int, k: int) -> int:
    """Calculates the number of combinations for choosing k items from n."""
    if k < 0 or k > n:
        raise ValueError("k must be between 0 and n")
    if k == 0 or k == n:
        return 1
    return calculate_combinations(n - 1, k - 1) + calculate_combinations(n - 1, k)

# Test cases
assert calculate_probability(30, 4) == 20.8
assert calculate_probability(10, 3) == 17.5



```

**Explanation:**

1. **`is_prime(num: int) -> bool`**: This function checks if a given number is prime. It iterates from 2 to the square root of the number, checking for divisibility. If any divisor is found, it's not prime; otherwise, it is.
2. **`calculate_probability(total_tickets: int, chosen_tickets: int) -> float`**: This function calculates the probability. It first counts the number of prime numbers within the given range. Then, it iterates through possible combinations of prime numbers to be chosen (at least 2). For each combination, it calculates the number of ways to choose the remaining non-prime tickets using `calculate_combinations`. Finally, it divides the number of successful combinations by the total number of possible combinations and multiplies by 100 to get the percentage.
3. **`calculate_combinations(n: int, k: int) -> int`**: This function calculates the number of combinations for choosing `k` items from a set of `n` items using recursion. It handles edge cases (k=0 or k=n) and recursively calculates combinations for smaller subproblems.

**Error Handling:**

- The `calculate_combinations` function raises a `ValueError` if `k` is less than 0 or greater than `n`, ensuring valid input for the combination calculation.



