    """Calculates the probability of having at least two prime numbers and an even sum."""

    # Calculate total possible combinations
    total_combinations = math.comb(total_tickets, chosen_tickets)

    # Calculate combinations with at least 2 primes and even sum
    favorable_combinations = 0
    for i in range(2, chosen_tickets + 1):  
        prime_count = 0
        for j in range(1, total_tickets + 1):
            if is_prime(j):
                prime_count += 1
        if prime_count >= i:
            favorable_combinations += math.comb(prime_count, i) * math.comb(total_tickets - prime_count, chosen_tickets - i)

    # Calculate and round the probability
    probability = (favorable_combinations / total_combinations) * 100
    return round(probability, 1)


