response_text:
```python
import numpy as np
from scipy.optimize import minimize_scalar

def g(x):
    return (x + 1)/(x - 2)

def distance_to_curve(point, curve):
    x = point[0]
    y = point[1]
    return np.abs(y - g(x))

def solve_min_distance(mx, my):
    result = minimize_scalar(lambda x: distance_to_curve((x, my), g))
    if result.success:
        return round(result.fun * 10, 2)
    else:
        raise ValueError("Failed to find minimum distance")

# Test cases
assert solve_min_distance(3, 2) == 10.35
assert solve_min_distance(0, 0) == 46.06
```

