response_text:
from scipy.optimize import minimize_scalar
import numpy as np

def calculate_revenue(price, customers):
    return price * customers / 1000

def calculate_cost(customers, coefficients):
    return sum(coeff * customer ** i for i, coeff in enumerate(reversed(coefficients)))

def maximize_profit_price(initial_price, initial_customers, price_decrease_per_customer, new_customers_per_price_decrease, cost_coefficients):
    def profit(price):
        customers = initial_customers + (price - initial_price) / price_decrease_per_customer * new_customers_per_price_decrease
        return calculate_revenue(price, customers) - calculate_cost(customers, cost_coefficients)

    result = minimize_scalar(lambda x: -profit(x), bounds=(0, initial_price))
    return round(result.x, 2)

# Test cases
assert maximize_profit_price(200, 400, 10, 50, [0.01, 28, 15000]) == 160.0
assert maximize_profit_price(300, 500, 20, 100, [0.02, 30, 20000]) == 231.82

