from typing import Dict, List

def calculate_final_value(n: int) -> float:
    """
    Calculate the value of N/8 + 16 given a certain number of ways to choose and place triangles.

    Args:
        n (int): The number of ways to choose and place triangles.

    Returns:
        float: The value of N/8 + 16.
    """

    # Define the colors and numbers for each triangle
    colors = ['Blue', 'Red', 'Yellow']
    numbers = [1, 2, 3, 4]

    # Initialize a dictionary to store the number of ways to place triangles on each face
    face_ways: Dict[str, int] = {color: {} for color in colors}
    for i in range(1, 5):
        face_ways['Blue'][i] = 0
        face_ways['Red'][i] = 0
        face_ways['Yellow'][i] = 0

    # Function to calculate the number of ways to place triangles on a given face
    def place_triangles(face: str, color: str, num: int) -> None:
        if n == 0:
            return
        if face not in face_ways[color]:
            face_ways[color][num] = 1
            return
        for c in colors:
            if c != color:
                for i in range(1, 5):
                    if i != num:
                        place_triangles(face, c, i)

    # Calculate the number of ways to place triangles on each face
    for i in range(1, 9):
        for j in range(1, 5):
            place_triangles(f'Face {i}', colors[j-1], numbers[j-1])

    # Calculate the total number of ways to choose and place triangles
    total_ways = 0
    for color in colors:
        for num in numbers:
            total_ways += face_ways[color][num]

    # Return the value of N/8 + 16
    return (total_ways / 8) + 16

# Test cases
assert calculate_final_value(1152) == 160.0
assert calculate_final_value(0) == 16.0

