import itertools

def calculate_p_scaled(num_slots, num_books, scale_factor):
    # Base case: if there are no books or slots, return 1 (only one way to distribute)
    if num_books == 0 or num_slots == 0:
        return 1

    # Initialize count of valid distributions
    count = 0

    # Try distributing the first book in each slot
    for i in range(num_slots):
        # If this is a valid distribution, recursively calculate the number of ways to distribute the remaining books
        if (i == 0 or num_books > 1 and i == num_slots - 1) and num_books > 1:
            count += calculate_p_scaled(num_slots - 2, num_books - 2, scale_factor)

    # If exactly 4 slots contain exactly 1 book, try distributing the first book in each of these slots
    for i in itertools.combinations(range(num_slots), 4):
        if len(i) == 4:
            count += calculate_p_scaled(num_slots - 4, num_books - 4, scale_factor)

    # If exactly 6 slots contain exactly 1 book, try distributing the first book in each of these slots
    for i in itertools.combinations(range(num_slots), 6):
        if len(i) == 6:
            count += calculate_p_scaled(num_slots - 6, num_books - 6, scale_factor)

    # Return the total count of valid distributions scaled by the given factor
    return count * scale_factor

# Test cases
assert round(calculate_p_scaled(10, 8, 12155), 0) == 131.0
assert round(calculate_p_scaled(5, 3, 100), 2) == 0.0

