def calculate_inverse_prob(start: int, end: int) -> int:
    if start > end or start < 10000 or end > 99999:
        return None

    total_numbers = end - start + 1
    valid_numbers = 0

    for num in range(start, end + 1):
        str_num = f"{num:05d}"  # Ensure the number is represented as a 5-digit string
        a1, a2, a3, a4, a5 = map(int, str_num)

        if (a1 <= a2 + 1) and (a2 + 1 <= a3 - 7) and (a3 - 7 < a4) and (a4 <= a5 + 2):
            valid_numbers += 1

    probability = valid_numbers / total_numbers
    return round(1 / probability)

# Test cases
assert calculate_inverse_prob(10000, 99999) == 506
assert calculate_inverse_prob(10000, 10000) == None

