def solve_min_products(fixed_cost: int, variable_cost: int, selling_price: int) -> int:
    def calculate_profit(x: int) -> bool:
        total_revenue = x * selling_price
        if x < 100:
            tax_rate = 0.10
        elif 100 <= x < 300:
            tax_rate = 0.08
        else:
            tax_rate = 0.05

        total_cost = fixed_cost + (x * variable_cost)
        net_revenue = total_revenue - (total_revenue * tax_rate)
        return net_revenue > total_cost

    x = 1
    while not calculate_profit(x):
        x += 1
    return x

# Test cases
assert solve_min_products(200, 1, 3) == 114
assert solve_min_products(100, 1, 3) == 59

