def calculate_tax(x: int) -> float:
    """Calculate tax based on quantity sold."""
    if x < 100:
        return 0.10 * (3 * x)
    elif 100 <= x < 300:
        return 0.08 * (3 * x)
    else:
        return 0.05 * (3 * x)

def solve_min_products(fixed_cost: int, variable_cost: int, selling_price: int) -> int:
    """
    Find the minimum number of products that must be produced and sold for the business to start making a profit.

    :param fixed_cost: Fixed monthly cost in VND
    :param variable_cost: Variable cost per product in VND
    :param selling_price: Selling price per product in VND
    :return: Minimum number of products (x) that must be produced and sold for the business to start making a profit.
    """
    x = 0
    while True:
        total_revenue = selling_price * x
        tax = calculate_tax(x)
        total_cost = fixed_cost + variable_cost * x
        profit = total_revenue - tax - total_cost

        if profit > 0:
            return x
        x += 1

