    def calculate_profit(x: int) -> float:
        # Calculate total revenue
        total_revenue = x * selling_price_per_product

        # Calculate total cost
        total_cost = fixed_cost + (x * variable_cost_per_product)

        # Calculate taxes based on the quantity sold
        if x < 100:
            tax_rate = 0.10
        elif 100 <= x < 300:
            tax_rate = 0.08
