    # Binary search to find the minimum number of products that make a profit > 0
    low, high = 1, 1000  # Initial range for binary search

    while low < high:
        mid = (low + high) // 2
        if calculate_profit(mid) <= 0:
            low = mid + 1
        else:
            high = mid

    return low

