from typing import Dict, Tuple

def solve_shortest_path(distances: Dict[Tuple[str, str], int]) -> int:
    def dfs(current_location: str, visited: set, path_length: int) -> int:
        if len(visited) == 4:
            return path_length

        min_distance = float('inf')

        for next_location in distances.keys():
            if next_location[0] == current_location and next_location not in visited:
                new_path_length = path_length + distances[next_location]
                visited.add(next_location)
                min_distance = min(min_distance, dfs(next_location[1], visited, new_path_length))
                visited.remove(next_location)  # Backtrack

        return min_distance

    start_location = 'M'
    initial_visited = {'M'}
    initial_path_length = 0
    return dfs(start_location, initial_visited, initial_path_length)

# Test cases
assert solve_shortest_path({('M','A'): 2, ('M','B'): 5, ('M','C'): 10, ('M','D'): 15, ('A','B'): 3, ('A','C'): 8, ('A','D'): 12, ('B','C'): 4, ('B','D'): 7, ('C','D'): 2}) == 11
assert solve_shortest_path({('M','A'): 1, ('M','B'): 1, ('M','C'): 1, ('M','D'): 1, ('A','B'): 1, ('A','C'): 1, ('A','D'): 1, ('B','C'): 1, ('B','D'): 1, ('C','D'): 1}) == 4

