def solve_shortest_path(distances: Dict[Tuple[str, str], int]) -> int:
    def dfs(current: str, visited: set, path_length: int) -> int:
        nonlocal min_distance

        # If all locations have been visited and we are at the last location
        if len(visited) == 4:
            return path_length + distances[(current, next_location)]

        # Explore all possible next steps
        for next_loc in families - visited:
            if (current, next_loc) in distances:
                new_path_length = dfs(next_loc, visited | {next_loc}, path_length + distances[(current, next_loc)])
                min_distance = min(min_distance, new_path_length)

        return min_distance

    # Set of all family locations
    families = {'A', 'B', 'C', 'D'}

    # Initialize the minimum distance to a large number
    min_distance = float('inf')

    # Start from school M and visit each possible first location
