from typing import List

def count_ap_triplets(n: int, max_sum: int) -> int:
    def is_arithmetic_progression(a: int, b: int, c: int) -> bool:
        return (b - a == c - b)

    count = 0
    for i in range(1, n + 1):
        for j in range(i + 1, n + 1):
            k = 2 * j - i
            if k > n or not is_arithmetic_progression(i, j, k) or (i + j + k > max_sum):
                continue
            count += 1

    return count

# Test cases
assert count_ap_triplets(100, 150) == 1225
assert count_ap_triplets(10, 30) == 20

