from typing import Callable

def calculate_win_probability(p: float) -> float:
    def binomial_coefficient(n: int, k: int) -> int:
        """Calculate binomial coefficient C(n, k)."""
        result = 1
        for i in range(1, k + 1):
            result *= (n - i + 1) / i
        return int(result)

    def probability_of_sequence(sequence: str) -> float:
        """Calculate the probability of a given sequence."""
        prob = 1.0
        for char in sequence:
            if char == 'A':
                prob *= p
            else:
                prob *= (1 - p)
        return prob

    # Calculate probabilities for each scenario
    scenarios = [
        "AAA",  # An wins in 3 sets
        "AAAB, AABA, BAAA",  # An wins in 4 sets
        "AABBAA, ABBAAB, BAABAA"  # An wins in 5 sets
    ]

    total_probability = 0.0

    for scenario in scenarios:
        if len(scenario) == 3:  # Scenario with 3 sets
            total_probability += probability_of_sequence(scenario)
        elif len(scenario) == 4:  # Scenario with 4 sets
            total_probability += binomial_coefficient(4, 2) * (probability_of_sequence(scenario))
        else:  # Scenario with 5 sets
            total_probability += binomial_coefficient(5, 3) * (probability_of_sequence(scenario))

    return round(total_probability, 2)

# Test cases
assert calculate_win_probability(0.4) == 0.32
assert calculate_win_probability(0.5) == 0.5

