from typing import Tuple

def min_distance_lizards(width: int, length: int, height: int,
                         x1: int, y1: int, x2: int, y2: int) -> int:
    # Unfold the room in different ways and calculate distances
    def unfold_and_calculate(x1, y1, x2, y2):
        min_distance = float('inf')

        # Case 1: No unfolding (lizards on same wall)
        if x1 == x2 or y1 == y2:
            distance = abs(x1 - x2) + abs(y1 - y2)
            min_distance = min(min_distance, distance)

        # Case 2: Unfold along width
        for i in range(0, length // width):
            if (x1 != x2 and y1 == y2) or (y1 != y2 and x1 == x2):
                distance = abs(x1 - x2) + abs(y1 - y2)
                min_distance = min(min_distance, distance)

        # Case 3: Unfold along length
        for i in range(0, width // height):
            if (x1 != x2 and y1 == y2) or (y1 != y2 and x1 == x2):
                distance = abs(x1 - x2) + abs(y1 - y2)
                min_distance = min(min_distance, distance)

        # Case 4: Unfold along both width and length
        for i in range(0, length // height):
            if (x1 != x2 and y1 == y2) or (y1 != y2 and x1 == x2):
                distance = abs(x1 - x2) + abs(y1 - y2)
                min_distance = min(min_distance, distance)

        return int(round(min_distance))

    # Calculate the minimum distance
    min_distance = unfold_and_calculate(x1, y1, x2, y2)

    return min_distance

# Test cases
assert min_distance_lizards(8, 12, 5, 7, 3, 9, 4) == 11
assert min_distance_lizards(8, 12, 5, 0, 0, 0, 0) == 8

