```python
from typing import List

def count_grid_ways(numbers: List[int]) -> int:
    from itertools import combinations, permutations

    def is_valid_combination(comb):
        # Check if the sum of each row is equal
        return (sum(comb[:3]) == sum(comb[3:5]) == sum(comb[5:]) and 
                len(set(comb)) == 6)

    valid_combinations = []
    for comb in combinations(numbers, 6):
        if is_valid_combination(comb):
            valid_combinations.append(comb)

    count = 0
    for comb in valid_combinations:
        for perm in permutations(comb):
            if is_valid_combination(perm):
                count += 1

    return count // len(valid_combinations)  # Each combination can be permuted in 6! ways, but we only need unique ones

# Test cases
assert count_grid_ways(list(range(2, 12))) == 36
assert count_grid_ways(list(range(1, 7))) == 0
```

