from typing import List

def count_grid_ways(numbers: List[int]) -> int:
    from itertools import combinations, permutations

    # Generate all possible combinations of the given numbers taken 6 at a time
    combos = combinations(numbers, 6)

    def is_valid_combination(comb):
        # Split combination into rows
        row1 = comb[:3]
        row2 = comb[3:5]
        row3 = (comb[5], )

        # Check if the sums of each row are equal
        return sum(row1) == sum(row2) == sum(row3)

    valid_combinations = 0

    for combo in combos:
        if is_valid_combination(combo):
            # Count unique permutations of this combination
            for perm in set(permutations(combo)):
                if is_valid_combination(perm[:6]):
                    valid_combinations += 1

    return valid_combinations // 720  # Each valid combination has 720 permutations

# Test cases
assert count_grid_ways(list(range(2, 12))) == 36
assert count_grid_ways(list(range(1, 7))) == 0

