def count_grid_ways(numbers):
    def is_valid_combination(comb):
        # Calculate the target sum for each row
        total_sum = sum(comb)
        if total_sum % 6 != 0:
            return False

        target_sum = total_sum // 6
        first_row_sum, second_row_sum, third_row_sum = 0, 0, 0

        # Try to place the numbers in a valid grid configuration
        for i in range(3):
            first_row_sum += comb[i]
        for i in range(3, 5):
            second_row_sum += comb[i]
        third_row_sum = comb[5]

        if first_row_sum == target_sum and second_row_sum == target_sum and third_row_sum == target_sum:
            return True
        return False

    valid_combinations_count = 0

    # Generate all combinations of six distinct numbers from the set {2, 3, ..., 11}
    for comb in combinations(numbers, 6):
        if is_valid_combination(comb):
            valid_combinations_count += 1

    return valid_combinations_count

