def count_grid_ways(numbers):
    # The target sum for each row (since there are 6 numbers, and we need to distribute them)
    total_sum = sum(numbers)
    target_row_sums = [total_sum // 3] * 3

    def is_valid_combination(combination):
        # Check if the combination can be split into three rows with equal sums
        for i in range(1 << len(combination)):
            row1, row2, row3 = [], [], []
            for j in range(len(combination)):
                if (i >> j) & 1:
                    row1.append(combination[j])
                elif (i >> (j - len(combination))) & 1:
                    row2.append(combination[j])
                else:
                    row3.append(combination[j])

            # Check if the sums of the rows are equal
            if sum(row1) == target_row_sums[0] and sum(row2) == target_row_sums[1] and sum(row3) == target_row_sums[2]:
                return True
        return False

    count = 0
    for comb in combinations(numbers, 6):
        if is_valid_combination(comb):
            count += 1

    return count

