def count_grid_ways(numbers):
    # Define the target sums for each row
    target_sums = [6, 5]  # The sum of the first row (3 cells) and the second row (2 cells)

    def is_valid_combination(comb):
        # Calculate the remaining number after choosing the combination
        remaining_numbers = set(numbers) - set(comb)

        # Check if we can form a valid third row with the remaining numbers
        for num in remaining_numbers:
            if sum(comb) + num == target_sums[0] and len(remaining_numbers) >= 1:
                return True
        return False

    count = 0
    for comb in combinations(numbers, 6):
        if is_valid_combination(comb):
            count += 1

    return count

# Test cases
assert count_grid_ways(list(range(2, 12))) == 36
assert count_grid_ways(list(range(1, 7))) == 0

