from typing import Tuple

def solve_silk_profit(max_production: int, budget: int, cost_brocade: int, days_brocade: int, cost_mulberry: int, days_mulberry: int, labor_cost: int, price_brocade: int, price_mulberry: int) -> float:
    # Define the objective function for profit
    def profit(x, y):
        return (price_brocade * x + price_mulberry * y) - (cost_brocade * x + cost_mulberry * y + labor_cost * (days_brocade * x + days_mulberry * y))

    # Define the constraints
    constraints = [
        lambda x, y: x + y <= max_production,
        lambda x, y: 20000 * x + 10000 * y + 40000 * (2 * x + y) <= budget
    ]

    # Initialize variables to store the maximum profit and corresponding values of x and y
    max_profit = -float('inf')
    best_x, best_y = 0, 0

    # Iterate over possible values of x and y within constraints
    for x in range(max_production + 1):
        for y in range(max_production + 1):
            if all(constraint(x, y) for constraint in constraints):
                current_profit = profit(x, y)
                if current_profit > max_profit:
                    max_profit = current_profit
                    best_x, best_y = x, y

    # Calculate the value of x + 3y that maximizes the daily profit
    return best_x + 3 * best_y

# Test cases
assert solve_silk_profit(100, 6000000, 20000, 2, 10000, 1, 40000, 150000, 80000) == 260.0
assert solve_silk_profit(100, 8000000, 20000, 2, 10000, 1, 40000, 150000, 80000) == 180.0

