from itertools import permutations

def count_rotor_arrangements(n: int, masses: list[int]) -> int:
    def is_equilateral_triangle(a, b, c):
        return (a + 1) % n == b and (b + 1) % n == c or \
               (a - 1) % n == b and (b - 1) % n == c

    def valid_groups(group1, group2, group3):
        total_mass = sum(group1)
        return set([sum(group1), sum(group2), sum(group3)]) == {total_mass}

    count = 0
    for perm in permutations(masses):
        # Check all possible groups of three equilateral triangles
        for i in range(n):
            if is_equilateral_triangle(i, (i + 3) % n, (i + 6) % n):
                group1 = [perm[i], perm[(i + 3) % n], perm[(i + 6) % n]]
                remaining_masses = list(set(masses) - set(group1))
                for j in range(len(remaining_masses)):
                    if is_equilateral_triangle(j, (j + 3) % n, (j + 6) % n):
                        group2 = [remaining_masses[j], remaining_masses[(j + 3) % n], remaining_masses[(j + 6) % n]]
                        group3 = list(set(remaining_masses) - set(group2))
                        if valid_groups(group1, group2, group3):
                            count += 1
    return count // 6

