def count_rotor_arrangements(n: int, masses: list[int]) -> int:
    if n != 9 or len(masses) != 9:
        raise ValueError("The number of slots and masses must be exactly 9.")

    # Function to check if three blades form an equilateral triangle
    def is_equilateral_triangle(a, b, c):
        return (a + 2 == b % n + 1 and b + 2 == c % n + 1) or \
               (b + 2 == a % n + 1 and c + 2 == a % n + 1) or \
               (c + 2 == b % n + 1 and a + 2 == b % n + 1)

    # Function to check if the current permutation satisfies the conditions
    def is_valid(arrangement):
        groups = []
        for i in range(3):
            group = [arrangement[i * 3], arrangement[(i * 3) + 1], arrangement[(i * 3) + 2]]
            if not all(is_equilateral_triangle(group[j], group[(j+1) % 3], group[(j+2) % 3]) for j in range(3)):
                return False
            groups.append(sum(group))
        return len(set(groups)) == 1

    count = 0
    for perm in permutations(masses):
        if is_valid(perm):
            count += 1

    return count

