def count_rotor_arrangements(n, masses):
    if n != 9 or len(masses) != 9:
        raise ValueError("The number of slots and masses must be exactly 9.")

    # Generate all possible groups of three positions that form equilateral triangles
    triangle_positions = [(i, (i + 3) % 9, (i + 6) % 9) for i in range(9)]

    def is_valid_group(group):
        return sum(masses[i] for i in group) == target_sum

    # Find the target sum of each group
    total_mass = sum(masses)
    if total_mass % 3 != 0:
        return 0
    target_sum = total_mass // 3

    valid_arrangements = set()

    def dfs(current_group, remaining_groups):
        nonlocal valid_arrangements

        # If we have formed all three groups, check the validity and add to results
        if len(remaining_groups) == 0:
            if is_valid_group(current_group):
                valid_arrangements.add(tuple(sorted(current_group)))
            return

        for group in remaining_groups:
            new_remaining = list(remaining_groups)
            new_remaining.remove(group)
            dfs(current_group + (group,), tuple(new_remaining))

    # Try all possible ways to form the groups
    for initial_group in triangle_positions:
        remaining_groups = set(triangle_positions) - {initial_group}
        dfs(initial_group, remaining_groups)

    return len(valid_arrangements)

# Test cases
