    def is_valid(arrangement):
        triangle_masses = set()

        for i in range(3):
            group = [arrangement[i], arrangement[i + 3], arrangement[i + 6]]
            total_mass = sum(group)
            if total_mass in triangle_masses:
                return False
            triangle_masses.add(total_mass)

        # Check that all groups have the same mass
        expected_mass = next(iter(triangle_masses))
        for group in combinations(arrangement, 3):
            if sum(group) != expected_mass:
                return False

        return True

    valid_count = 0

    # Generate all permutations of masses and check each one
    for perm in permutations(masses):
        if is_valid(perm):
            valid_count += 1

    return valid_count

