from itertools import permutations

def is_equilateral_triangle(slots):
    # Check if the slots form an equilateral triangle (3 positions apart)
    n = len(slots)
    for i in range(n):
        if not ((slots[(i + 1) % n] - slots[i]) == 2 or (slots[(i + 1) % n] - slots[i]) == -7):
            return False
    return True

def count_rotor_arrangements(n, masses):
    # Generate all possible groups of three masses that sum up to 15
    valid_groups = []
    for i in range(len(masses)):
        for j in range(i + 1, len(masses)):
            for k in range(j + 1, len(masses)):
                if masses[i] + masses[j] + masses[k] == 15:
                    valid_groups.append((masses[i], masses[j], masses[k]))

    # Generate all permutations of the groups
    unique_arrangements = set()
