def is_equilateral_triangle(slots):
    # Check if the slots form an equilateral triangle (3 positions apart)
    n = len(slots)
    for i in range(n):
        if not ((slots[(i + 1) % n] - slots[i]) == 2 or (slots[(i + 1) % n] - slots[i]) == -7):
