```python
from typing import *
from itertools import product

def calculate_3430p(n: int) -> float:
    # Generate all possible combinations for a single row (since the sum of each row must be 0)
    valid_rows = []
    for combination in product([-1, 0, 1], repeat=3):
        if sum(combination) == 0:
            valid_rows.append(combination)

    total_combinations = len(valid_rows) ** 3
    successful_combinations = 0

    # Iterate over all possible combinations of rows
    for row1 in valid_rows:
        for row2 in valid_rows:
            for row3 in valid_rows:
                grid = [row1, row2, row3]
                col_sums = [sum(column) for column in zip(row1, row2, row3)]
                if all(s == 0 for s in col_sums):
                    successful_combinations += 1

    # Calculate the probability
    p = successful_combinations / total_combinations
    return round(n * p, 6)

# Test cases
assert round(calculate_3430p(3430), 2) == 310.0
assert round(calculate_3430p(1), 6) == 0.090379
```

