from typing import *
from itertools import product

def calculate_3430p(multiplier: int) -> float:
    # Generate all possible combinations for a 3x3 grid with values -1, 0, 1
    valid_grids = []
    for row1 in product([-1, 0, 1], repeat=3):
        if sum(row1) == 0:
            for row2 in product([-1, 0, 1], repeat=3):
                if sum(row2) == 0:
                    for row3 in product([-1, 0, 1], repeat=3):
                        if sum(row3) == 0:
                            valid_grids.append((row1, row2, row3))

    total_valid_grids = len(valid_grids)
    count_sum_columns_zero = 0

    # Check each grid to see if the column sums are also zero
    for grid in valid_grids:
        col_sums = [grid[0][i] + grid[1][i] + grid[2][i] for i in range(3)]
        if all(col_sum == 0 for col_sum in col_sums):
            count_sum_columns_zero += 1

    # Calculate the probability
    p = count_sum_columns_zero / total_valid_grids
    return multiplier * p

# Test cases
assert round(calculate_3430p(3430), 2) == 310.0
assert round(calculate_3430p(1), 6) == 0.090379
```

