from math import comb

def calculate_probability_score(n: int, correct_points: int, incorrect_points: int, target_score: int) -> float:
    p = 1 / 4  # Probability of answering a question correctly

    total_prob = 0.0

    for k in range(n + 1):
        if (correct_points * k - incorrect_points * (n - k)) == target_score:
            prob_k_correct = comb(n, k) * (p ** k) * ((1 - p) ** (n - k))
            total_prob += prob_k_correct

    return round(total_prob * 100, 2)

# Test cases
assert calculate_probability_score(10, 4, -1, 20) == 1.62
assert calculate_probability_score(10, 4, -1, 40) == 0.0

print("All test cases passed!")

