from typing import Tuple

def binomial_probability(n: int, k: int, p: float) -> float:
    from math import comb

    return comb(n, k) * (p ** k) * ((1 - p) ** (n - k))

def calculate_probability_score(total_questions: int, points_per_correct: int, points_per_incorrect: int, target_score: int) -> float:
    if total_questions <= 0 or points_per_correct < 0 or points_per_incorrect < 0 or target_score < 0:
        raise ValueError("Invalid input values")

    # Calculate the required number of correct answers
    k = (target_score - total_questions * points_per_incorrect) / (points_per_correct + points_per_incorrect)

    if not k.is_integer() or k < 0 or k > total_questions:
        return 0.0

    k = int(k)

    # Calculate the probability
    p = 1/4  # Probability of answering correctly
    probability = binomial_probability(total_questions, k, p)

    return round(probability * 100, 2)

# Test cases
assert calculate_probability_score(10, 4, -1, 20) == 1.62
assert calculate_probability_score(10, 4, -1, 40) == 0.0

print(calculate_probability_score(10, 4, -1, 20))

