from typing import Tuple

def cross_product(v1: Tuple[float, float, float], v2: Tuple[float, float, float]) -> Tuple[float, float, float]:
    return (v1[1]*v2[2] - v1[2]*v2[1],
            v1[2]*v2[0] - v1[0]*v2[2],
            v1[0]*v2[1] - v1[1]*v2[0])

def dot_product(v1: Tuple[float, float, float], v2: Tuple[float, float, float]) -> float:
    return v1[0]*v2[0] + v1[1]*v2[1] + v1[2]*v2[2]

def distance_point_to_line(point: Tuple[float, float, float], line_start: Tuple[float, float, float], line_end: Tuple[float, float, float]) -> float:
    vec_AP = (point[0] - line_start[0], point[1] - line_start[1], point[2] - line_start[2])
    vec_AB = (line_end[0] - line_start[0], line_end[1] - line_start[1], line_end[2] - line_start[2])
    cross_product_AP_AB = cross_product(vec_AP, vec_AB)
    distance = dot_product(cross_product_AP_AB, cross_product(vec_AB, vec_AB)) / (dot_product(vec_AB, vec_AB) ** 0.5)
    return abs(distance)

def solve_gps_problem(A: Tuple[float, float, float], B: Tuple[float, float, float], C: Tuple[float, float, float], D: Tuple[float, float, float]) -> float:
    def sum_of_distances(t):
        M = (3*t, 4 - 4*t, 5)
        return distance_point_to_line(A, B, M) + distance_point_to_line(B, B, M) + distance_point_to_line(C, B, M)

    from scipy.optimize import minimize_scalar
    result = minimize_scalar(lambda t: -sum_of_distances(t), bounds=(0, 1), method='bounded')
    optimal_t = result.x
    M_optimal = (3*optimal_t, 4 - 4*optimal_t, 5)
    return sum(M_optimal)

# Test cases
assert round(solve_gps_problem((0, 4, 5), (3, 0, 5), (3, 4, 0), (3, 4, 5)), 2) == 8.64
assert round(solve_gps_problem((0, 0, 0), (1, 0, 0), (0, 1, 0), (1, 1, 0)), 2) == 1.0

