from typing import List, Tuple
import itertools

# Define the adjacency relationships for an octahedron
adjacency = [
    (0, 1), (0, 2), (0, 3),
    (1, 4), (1, 5),
    (2, 4), (2, 6),
    (3, 5), (3, 6),
    (4, 7),
    (5, 7),
    (6, 7)
]

def is_valid_coloring(colors: List[int]) -> bool:
    """Check if the given coloring satisfies the adjacency constraint."""
    for u, v in adjacency:
        if colors[u] == colors[v]:
            return False
    return True

def count_ways() -> int:
    """Count the number of valid ways to color and number the triangles."""
    # Generate all possible colorings (4 choices per face)
    total_ways = 0

    for colors in itertools.product(range(3), repeat=8):
        if is_valid_coloring(colors):
            numbers = list(itertools.permutations(range(1, 5)))
            for num_permutation in numbers:
                valid = True
                # Check the vertex sharing constraint
                for u, v in adjacency:
                    if colors[u] == colors[v]:
                        continue
                    if num_permutation[colors[u]] == num_permutation[colors[v]]:
                        valid = False
                        break
                if valid:
                    total_ways += 1

    return total_ways

def calculate_final_value(total_ways: int) -> float:
    """Calculate the final value based on the number of ways."""
    return (total_ways // 8) + 16.0

# Test cases
assert calculate_final_value(count_ways()) == 160.0, "Test case failed"
print("All test cases passed!")

