import math

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def calculate_probability(total_tickets: int, chosen_tickets: int) -> float:
    total_combinations = math.comb(total_tickets, chosen_tickets)

    prime_numbers = [i for i in range(1, total_tickets + 1) if is_prime(i)]
    non_primes = [i for i in range(1, total_tickets + 1) if not is_prime(i)]

    valid_combinations = 0

    # Case 1: Exactly 2 prime numbers and the sum of the 4 numbers is even
    for primes in math.combinations(prime_numbers, 2):
        remaining = chosen_tickets - 2
        for non_primes_in_remaining in math.combinations(non_primes, remaining):
            if (sum(primes) + sum(non_primes_in_remaining)) % 2 == 0:
                valid_combinations += 1

    # Case 2: Exactly 4 prime numbers and the sum of the 4 numbers is even
    for primes in math.combinations(prime_numbers, 4):
        if (sum(primes)) % 2 == 0:
            valid_combinations += 1

    probability = (valid_combinations / total_combinations) * 100
    return round(probability, 1)

# Test cases
assert calculate_probability(30, 4) == 20.8
assert calculate_probability(10, 3) == 17.5

print("All test cases passed.")
```

