```python
from typing import Tuple
import math

def is_prime(n: int) -> bool:
    if n <= 1:
        return False
    for i in range(2, int(math.sqrt(n)) + 1):
        if n % i == 0:
            return False
    return True

def calculate_probability(total_tickets: int, chosen_tickets: int) -> float:
    prime_numbers = [i for i in range(1, total_tickets + 1) if is_prime(i)]
    non_primes = [i for i in range(1, total_tickets + 1) if not is_prime(i)]

    def combinations_count(lst: list, k: int) -> int:
        return math.comb(len(lst), k)

    # Calculate the number of ways to choose at least 2 prime numbers
    ways_with_at_least_2_primes = (combinations_count(prime_numbers, 2) * 
                                   combinations_count(non_primes, chosen_tickets - 2)) + \
                                  (combinations_count(prime_numbers, 3) * 
                                   combinations_count(non_primes, chosen_tickets - 3)) + \
                                  (combinations_count(prime_numbers, 4))

    # Calculate the total number of ways to choose any 4 tickets
    total_ways = math.comb(total_tickets, chosen_tickets)

    # Calculate the probability that the sum is even
    def is_sum_even(primes: int, non_primes: int) -> bool:
        return (primes % 2 == 0 and non_primes % 2 != 0) or \
               (primes % 2 != 0 and non_primes % 2 == 0)

    ways_with_even_sum = sum(combinations_count(prime_numbers, p) * 
                             combinations_count(non_primes, n)
                             for p in range(2, min(chosen_tickets + 1, len(prime_numbers) + 1))
                             for n in range(chosen_tickets - p + 1)
                             if is_sum_even(p, n))

    valid_ways = ways_with_at_least_2_primes * (ways_with_even_sum / total_ways)

    probability = valid_ways / total_ways
    return round(probability * 100, 1)

# Test cases
assert calculate_probability(30, 4) == 20.8
assert calculate_probability(10, 3) == 17.5
